import { atom, read, update } from 'claude-code'
import type { EngineInterface, RenderChildren, Register, ToolCallInput } from 'claude-code'

import type { GateVerdict } from '../types'
import {
  classifyBash,
  clip,
  denyReason,
  formatLeft,
  gatedBash,
  gatedMcp,
  headline,
  logLine,
  mcpLines,
  normalize,
  parseDuration,
  parseMode,
} from './logic'
import type { BashGate, Decision, Gated, Mode, PathContext } from './logic'

// Session state lives in $.state so a hot reload keeps an active `/gate off`.
const off = atom({ plugin: 'outward-gate', key: 'off' } as const, null)
// Files a Write created this session (never ones it overwrote): an exact-match rm of one skips the dialog.
const created = atom({ plugin: 'outward-gate', key: 'created' } as const, [])
const CREATED_MAX = 500

const LOG = '/.claude/state/outward-gate.log'
const GUARD = '/.claude/hooks/guard_destructive_bash.sh'
const SLOT_PREFIX = 'og-'

// The dialog's answer channel. The question's answer, the timeout and an interrupt settle
// `verdict`. The tool.call hook waits through `$.gate.wait` (added in engine.create):
// time inside a `$` call doesn't count against the hook's 10 s budget, but the engine
// also wants each `$.gate.wait` answered within 10 s. So a pulse every PULSE_MS
// answers 'pending' and the hook simply asks again.
const PULSE_MS = 5_000
type Slot = {
  verdict: Promise<GateVerdict>
  resolve: (v: GateVerdict) => void
  tick: Promise<'pending'>
  fireTick: () => void
}
const slots = new Map<string, Slot>()

function newTick(): { tick: Promise<'pending'>; fireTick: () => void } {
  let fireTick: () => void = () => undefined
  const tick = new Promise<'pending'>(r => (fireTick = () => r('pending')))
  return { tick, fireTick }
}

function arm(id: string): void {
  let resolve: (v: GateVerdict) => void = () => undefined
  const verdict = new Promise<GateVerdict>(r => (resolve = r))
  slots.set(id, { verdict, resolve, ...newTick() })
}

function settle(id: string, verdict: GateVerdict): void {
  slots.get(id)?.resolve(verdict) // a second settle is a no-op: a promise resolves once
}

function pulse(id: string): void {
  const slot = slots.get(id)
  if (slot === undefined) return
  slot.fireTick()
  slots.set(id, { ...slot, ...newTick() })
}

function waitOnce(id: string): Promise<GateVerdict | 'pending'> {
  const slot = slots.get(id)
  return slot === undefined ? Promise.resolve('denied') : Promise.race([slot.verdict, slot.tick])
}

type Current = { mode: Mode; offBy?: string; until?: number | null }

/** The manifest's userConfig, read once per load. */
type Config = { mode: Mode; timeoutMin: number; vaultRoot: string }

/** Cheap synchronous pre-filter so ordinary tool calls pay nothing. */
function isCandidate(e: ToolCallInput): boolean {
  if (e.tool === 'Bash') return /\b(git|rm|trash|push)\b|\.Trash|-delete\b/.test(e.command)
  return gatedMcp(e.tool) !== undefined
}

function mcpInput(e: ToolCallInput): Readonly<Record<string, unknown>> {
  const input: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(e)) if (k !== 'tool' && k !== 'tool_use_id' && k !== 'agentId') input[k] = v
  return input
}

async function home($: EngineInterface): Promise<string> {
  return (await $.env.get('HOME')) ?? ''
}

async function current($: EngineInterface, now: number, cfg: Config): Promise<Current> {
  const env = parseMode((await $.env.get('OUTWARD_GATE'))?.trim().toLowerCase())
  if (env === 'off') return { mode: 'off', offBy: 'OUTWARD_GATE=off' }
  const base = env ?? cfg.mode
  if (base === 'off') return { mode: 'off', offBy: 'config' }
  const s = await read($, off)
  if (s !== null && (s.until === null || s.until > now)) return { mode: 'off', offBy: '/gate off', until: s.until }
  return { mode: base }
}

async function refreshStatus($: EngineInterface, cfg: Config): Promise<void> {
  if ((await $.session.surfaces()).length === 0) return
  const now = await $.clock.now()
  const s = await read($, off)
  if (s !== null && s.until !== null && s.until <= now) {
    await update($, off, () => null)
    $.ui.toast('outward-gate: gate back ON')
  }
  const c = await current($, now, cfg)
  if (c.mode !== 'off') return $.ui.status(undefined)
  const left = typeof c.until === 'number' ? ` · ${formatLeft(c.until - now)} left` : ''
  $.ui.status(`gate OFF${left}${c.offBy === '/gate off' ? '' : ` (${c.offBy})`}`)
}

/** Session switch, shared by `/gate` and the band's buttons: `ms` null = until turned on. */
async function setOff($: EngineInterface, cfg: Config, ms: number | null): Promise<void> {
  const now = await $.clock.now()
  await update($, off, () => ({ until: ms === null ? null : now + ms }))
  await refreshStatus($, cfg)
}

async function setOn($: EngineInterface, cfg: Config): Promise<void> {
  await update($, off, () => null)
  await refreshStatus($, cfg)
}

function hhmm(ms: number): string {
  const at = new Date(ms)
  return `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`
}

async function writeLog($: EngineInterface, decision: Decision, mode: Mode, tool: string, summary: string): Promise<void> {
  try {
    const line = logLine({ at: await $.clock.now(), session: await $.session.id(), mode, tool, summary, decision })
    // O_APPEND via the shell: concurrent sessions can't clobber each other's lines.
    await $.process.run(['/bin/sh', '-c', 'mkdir -p "$(dirname "$1")" && printf "%s\\n" "$2" >> "$1"', 'sh', `${await home($)}${LOG}`, line])
  } catch (err) {
    $.ui.log(`outward-gate: audit log write failed: ${String(err)}`, { to: 'debug' })
  }
}

async function pathContext($: EngineInterface, cfg: Config): Promise<PathContext> {
  const h = await home($)
  // Empty = no vault: every rm outside temp/session files counts as outside it (fail closed).
  const vaultRoot = cfg.vaultRoot === '' ? null : cfg.vaultRoot.replace(/^~(?=\/|$)/, h)
  // The session scratchpad lives under /private/tmp; $TMPDIR is macOS's per-user /var/folders/…/T.
  const tmp = (await $.env.get('TMPDIR'))?.trim()
  const tmpRoots = ['/tmp', '/private/tmp', ...(tmp ? [tmp, ...(tmp.startsWith('/var/') ? [`/private${tmp}`] : [])] : [])]
  return { cwd: await $.session.cwd(), home: h, vaultRoot, tmpRoots, created: await read($, created) }
}

/** After a call that removed session files: forget them, so a later file at that path asks again. */
async function forget($: EngineInterface, paths: readonly string[]): Promise<void> {
  if (paths.length) await update($, created, list => list.filter(p => !paths.includes(p)))
}

/** True when guard_destructive_bash.sh would hard-block it anyway: skip the dialog, no double prompt. */
async function guardBlocks($: EngineInterface, h: string, command: string): Promise<boolean> {
  try {
    const r = await $.process.run(['bash', `${h}${GUARD}`], { stdin: JSON.stringify({ tool_input: { command } }) })
    return r.exitCode === 2
  } catch {
    return false
  }
}

async function workflowName($: EngineInterface, workflowId: string): Promise<string | undefined> {
  try {
    const r = await $.tool.call({ tool: 'mcp__n8n-mcp__get_workflow_details', workflowId, detailLevel: 'execution' })
    if (r.deny !== undefined || typeof r.text !== 'string') return undefined
    const parsed: unknown = JSON.parse(r.text)
    if (typeof parsed !== 'object' || parsed === null || !('workflow' in parsed)) return undefined
    const wf = parsed.workflow
    return typeof wf === 'object' && wf !== null && 'name' in wf && typeof wf.name === 'string' ? wf.name : undefined
  } catch {
    return undefined
  }
}

/** What the call needs (BashGate shape for every tool); undefined = nothing to gate or log. */
async function classify($: EngineInterface, cfg: Config, e: ToolCallInput): Promise<BashGate | undefined> {
  if (e.tool === 'Bash') {
    const ctx = await pathContext($, cfg)
    const r = classifyBash(e.command, ctx)
    if (r.gated === undefined && r.exempt.length === 0) return undefined
    return (await guardBlocks($, ctx.home, e.command)) ? undefined : r
  }
  const title = gatedMcp(e.tool)
  if (title === undefined) return undefined
  const input = mcpInput(e)
  const lines = mcpLines(input)
  return { gated: { title, lines, summary: lines.join('; ') }, exempt: [], createdHits: [] }
}

/** Adds the workflow's name to an n8n dialog (only when a dialog will actually show). */
async function enrich($: EngineInterface, e: ToolCallInput, gated: Gated): Promise<Gated> {
  const workflowId = mcpInput(e).workflowId
  if (!gated.title.startsWith('n8n') || typeof workflowId !== 'string') return gated
  const name = await workflowName($, workflowId)
  return name === undefined ? gated : { ...gated, lines: [`workflow: ${name}`, ...gated.lines], summary: `${name}; ${gated.summary}` }
}

async function confirm($: EngineInterface, toolUseId: string, gated: Gated, signal: AbortSignal, cfg: Config): Promise<GateVerdict> {
  const id = `${SLOT_PREFIX}${toolUseId.replace(/[^A-Za-z0-9_-]/g, '').slice(-56)}`
  const ms = cfg.timeoutMin * 60_000
  arm(id)
  const deadline = (await $.clock.now()) + ms
  const timer = $.clock.after(ms, () => settle(id, 'timed-out'))
  const pulser = $.clock.every(PULSE_MS, () => pulse(id))
  const onAbort = () => settle(id, 'denied')
  signal.addEventListener('abort', onAbort)
  try {
    // The engine's own question dialog, inline at the prompt. Deny is listed first and only an
    // exact "Approve" approves, so a default pick, an idle auto-resolve, typed text or Esc all deny.
    // $.ui.ask can't be cancelled: after a timeout the question stays up, and a late answer is a no-op.
    const details = clip(gated.lines.join(' · '), 240)
    const question = `Claude wants to ${headline(gated.title)}${details ? ` — ${details}` : ''}. Allow? (auto-deny ${hhmm(deadline)})`
    void $.ui.ask(question, { options: ['Deny', 'Approve'], header: 'Outward gate' }).then(
      a => settle(id, a === 'Approve' ? 'approved' : 'denied'),
      () => settle(id, 'denied'),
    )
    let verdict = await $.gate.wait({ id })
    while (verdict === 'pending') verdict = await $.gate.wait({ id })
    return verdict
  } finally {
    timer.cancel()
    pulser.cancel()
    signal.removeEventListener('abort', onAbort)
    slots.delete(id)
  }
}

export const register: Register = (on, options) => {
  const cfg: Config = {
    mode: parseMode(options.mode) ?? 'auto',
    timeoutMin: typeof options.timeoutMinutes === 'number' && options.timeoutMinutes > 0 ? options.timeoutMinutes : 10,
    vaultRoot: typeof options.vaultRoot === 'string' ? options.vaultRoot.trim() : '',
  }

  on('engine.create', async ($, e, next) => {
    const built = await next(e)
    return { ...built, gate: { wait: ({ id }: { id: string }) => waitOnce(id) } }
  })

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'gate',
      description: 'outward-gate: status, on, off [8h], log',
      argumentHint: '[on | off [8h|30m] | log]',
    })
    $.clock.every(15_000, () => void refreshStatus($, cfg))
    await refreshStatus($, cfg)
    return next(e)
  })

  on('command.run', { command: 'gate' }, async ($, e) => {
    const [verb = '', arg = ''] = e.args.trim().split(/\s+/)
    const now = await $.clock.now()
    if (verb === 'on') {
      await setOn($, cfg)
      const c = await current($, now, cfg)
      return { text: c.mode === 'off' ? `Session switch cleared, but the gate stays OFF (${c.offBy}).` : 'outward-gate: ON.' }
    }
    if (verb === 'off') {
      const ms = arg === '' ? null : parseDuration(arg)
      if (ms === undefined) return { text: `Can't read "${arg}". Use e.g. /gate off 8h, /gate off 30m, or /gate off.` }
      await setOff($, cfg, ms)
      return {
        text: `outward-gate: OFF${ms === null ? ' until /gate on' : ` for ${formatLeft(ms)} (back ON automatically)`}. Gated actions still go to the audit log; your permission rules and shell guards still apply.`,
      }
    }
    if (verb === 'log') {
      const path = `${await home($)}${LOG}`
      const r = await $.process.run(['tail', '-n', '20', path]).catch(() => undefined)
      return { text: r && r.exitCode === 0 && r.stdout.trim() ? r.stdout.trimEnd() : `No log yet at ${path}.` }
    }
    if (verb !== '') return { text: 'Usage: /gate [on | off [8h|30m] | log]' }
    const c = await current($, now, cfg)
    const headless = (await $.session.surfaces()).length === 0
    const state =
      c.mode === 'off'
        ? `OFF (${c.offBy}${typeof c.until === 'number' ? `, ${formatLeft(c.until - now)} left` : ''})`
        : headless
          ? `ON in mode ${c.mode}, but this session is headless (${c.mode === 'on' ? 'gated calls are denied' : 'gated calls pass, logged'})`
          : `ON (mode ${c.mode}; unanswered dialogs auto-deny after ${cfg.timeoutMin} min)`
    return { text: `outward-gate: ${state}. Log: ~${LOG}` }
  })

  on('tool.call', async ($, e, next) => {
    if (!isCandidate(e)) return next(e)
    const r = await classify($, cfg, e)
    if (r === undefined) return next(e)
    const run = async () => {
      const result = await next(e)
      await forget($, r.createdHits)
      return result
    }

    const now = await $.clock.now()
    const c = await current($, now, cfg)
    const gated = r.gated
    if (gated === undefined) {
      // Every target is a temp file or one this session wrote: no dialog, still logged.
      await writeLog($, 'exempt', c.mode, e.tool, r.exempt.join('; '))
      return run()
    }
    const headless = (await $.session.surfaces()).length === 0
    if (c.mode === 'off') {
      await writeLog($, 'bypassed-off', c.mode, e.tool, gated.summary)
      return run()
    }
    if (headless) {
      if (c.mode === 'on') {
        await writeLog($, 'denied', c.mode, e.tool, gated.summary)
        return { deny: denyReason(gated.title, 'headless-strict', cfg.timeoutMin) }
      }
      await writeLog($, 'bypassed-headless', c.mode, e.tool, gated.summary)
      return run()
    }

    const shown = await enrich($, e, gated)
    const verdict = await confirm($, e.tool_use_id, shown, next.signal, cfg)
    await writeLog($, verdict, c.mode, e.tool, shown.summary)
    return verdict === 'approved' ? run() : { deny: denyReason(shown.title, verdict, cfg.timeoutMin) }
  }).catch(($, e, next) => {
    // Fail closed for gated calls only; a broken gate must never block unrelated tools.
    const unknown = { cwd: '/', home: '', vaultRoot: null, tmpRoots: [], created: [] }
    const gated = e.tool === 'Bash' ? gatedBash(e.command, unknown) : gatedMcp(e.tool)
    return gated === undefined ? next(e) : { deny: `outward-gate failed closed (${next.error.message}). Do not retry; list this action in your closeout.` }
  })

  // Record files a Write creates (main loop or subagent: both pass through tool.call). A Write
  // that overwrote an existing file never qualifies; stat before next(e) decides which it is.
  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const path = e.file_path.startsWith('/') ? normalize(e.file_path) : undefined
    const existed = path === undefined || (await $.fs.exists(path).catch(() => true))
    const result = await next(e)
    if (existed || result.deny !== undefined || result.isError === true) return result
    try {
      const st = await $.fs.stat(path, { resolve: true })
      if (st.kind === 'file') {
        const add = [path, ...(st.realPath !== undefined && st.realPath !== path ? [st.realPath] : [])]
        await update($, created, list => [...list.filter(p => !add.includes(p)), ...add].slice(-CREATED_MAX))
      }
    } catch (err) {
      $.ui.log(`outward-gate: could not record a created file: ${String(err)}`, { to: 'debug' })
    }
    return result
  })

  // The toggle band above the prompt: one row, a person's press only (the model has no
  // tool that reaches it). No hotkeys, so a stray keystroke in the composer can't flip it.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || e.props.view.agentId !== undefined) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    // The band is one site shared by every mod: stack our row on what the mods beneath draw, never replace it.
    const withBelow = async (mine: RenderChildren) => <Box flexDirection="column">{mine}{await next(e)}</Box>
    const c = await current($, await $.clock.now(), cfg)
    const what = 'outward gate'
    if (c.mode === 'off') {
      const when = c.offBy !== '/gate off' ? `(${c.offBy})` : typeof c.until === 'number' ? `until ${hhmm(c.until)}` : 'until turned on'
      return withBelow(
        <Box flexDirection="row">
          <Text color="yellow">○ </Text>
          <Text dimColor>{what} off {when}</Text>
          {c.offBy === '/gate off' ? <Text dimColor> · </Text> : null}
          {c.offBy === '/gate off' ? <Button key="gate-on" plain label="turn on" onPress={() => void setOn($, cfg)} /> : null}
        </Box>
      )
    }
    return withBelow(
      <Box flexDirection="row">
        <Text color="green">● </Text>
        <Text dimColor>{what} on</Text>
        <Text dimColor>{" · "}</Text>
        <Button key="gate-off-1h" plain dimColor label="off 1h" onPress={() => void setOff($, cfg, 3_600_000)} />
        <Text dimColor> · </Text>
        <Button key="gate-off-8h" plain dimColor label="off 8h" onPress={() => void setOff($, cfg, 8 * 3_600_000)} />
      </Box>
    )
  })
}

