// Pure helpers: what is gated, how its payload is summarised, how the
// off switch and the log line read. No `$` here, so tests call it directly.

export type Mode = 'auto' | 'on' | 'off'
export type Decision = 'approved' | 'denied' | 'timed-out' | 'bypassed-off' | 'bypassed-headless' | 'exempt'

/** A gated call: dialog title, payload lines, and the one-line log summary. */
export type Gated = { title: string; lines: string[]; summary: string }

/**
 * Where paths resolve: the Bash cwd, $HOME, and the vault root (null = unknown, gate everything);
 * plus what a delete may skip the dialog for: temp roots, and files this session created.
 */
export type PathContext = {
  cwd: string
  home: string
  vaultRoot: string | null
  /** /tmp, /private/tmp, $TMPDIR: a target strictly under one is exempt. */
  tmpRoots: readonly string[]
  /** Absolute paths a Write created this session: an exact match is exempt. */
  created: readonly string[]
}

// Add a row per service that sends, publishes or deletes (and its wording in MCP_PHRASE).
// Force pushes / dangerous rm -rf defer to guard_destructive_bash.sh when present (see README).
const MCP_GATED: readonly [RegExp, string][] = [
  [/^mcp__claude_ai_Gmail__(send_message|reply|forward|trash_\w+)$/, 'Gmail'],
  [/^mcp__n8n-mcp__(execute_workflow|test_workflow|publish_workflow|unpublish_workflow|archive_workflow)$/, 'n8n'],
  [/^mcp__raindrop-official__(delete_\w+|merge_collections)$/, 'Raindrop'],
]

// Allow-list of input keys shown in the dialog and log. Bodies (body, htmlBody,
// forwardText, inputs, attachment content) never match, so they never leak.
const SHOWN_KEY = /^(to|cc|bcc|subject|replyAll|executionMode|triggerNodeName|tags|\w*Ids?|\w*_ids?)$/

export function gatedMcp(tool: string): string | undefined {
  for (const [re, service] of MCP_GATED) {
    const m = re.exec(tool)
    if (m) return `${service} · ${m[1]}`
  }
  return undefined
}

const MCP_PHRASE: Readonly<Record<string, string>> = {
  send_message: 'send an email',
  reply: 'reply to an email',
  forward: 'forward an email',
  execute_workflow: 'run an n8n workflow',
  test_workflow: 'test-run an n8n workflow (every node but the trigger runs for real)',
  publish_workflow: 'publish an n8n workflow',
  unpublish_workflow: 'unpublish an n8n workflow',
  archive_workflow: 'archive an n8n workflow',
  merge_collections: 'merge Raindrop collections',
}

/** "Gmail · send_message" → "send an email"; a Bash title is already plain. Reads after "Claude wants to". */
export function headline(title: string): string {
  const [service = '', op] = title.split(' · ')
  if (op === undefined) return title
  const phrase = MCP_PHRASE[op]
  if (phrase !== undefined) return phrase
  if (op.startsWith('trash_')) return `trash a Gmail ${op.slice(6)}`
  if (op.startsWith('delete_')) return `delete Raindrop ${op.slice(7).replace(/_/g, ' ')}`
  return `${service} ${op}`
}

function show(value: unknown): string | undefined {
  if (typeof value === 'string') return clip(value, 100)
  if (typeof value === 'number' || typeof value === 'boolean') return String(value)
  if (Array.isArray(value)) {
    const items = value.filter(v => typeof v === 'string' || typeof v === 'number').map(String)
    const head = items.slice(0, 5).join(', ')
    return `${value.length} item${value.length === 1 ? '' : 's'}${head ? `: ${head}` : ''}${items.length > 5 ? ', …' : ''}`
  }
  return undefined
}

/** Payload lines for an MCP call: allow-listed keys only, plus an attachment count. */
export function mcpLines(input: Readonly<Record<string, unknown>>): string[] {
  const lines: string[] = []
  for (const [key, value] of Object.entries(input)) {
    if (key === 'attachments' && Array.isArray(value)) {
      lines.push(`attachments: ${value.length}`)
      continue
    }
    if (!SHOWN_KEY.test(key)) continue
    const shown = show(value)
    if (shown !== undefined) lines.push(`${key}: ${shown}`)
  }
  return lines
}

// ---- Bash -------------------------------------------------------------------
//
// Fail closed: a delete whose target can't be placed counts as outside the vault,
// and a command that mentions git and push in a shape the parser doesn't know is
// gated. Fail quiet: a delete under a temp root, or of a file this session wrote,
// passes with no dialog (logged `exempt`).

/** A heredoc operator at `i` (`<<`, `<<-`; not `<<<`): its delimiter, and where the operator ends. */
function heredoc(s: string, i: number): { delim: string; strip: boolean; quoted: boolean; end: number } | undefined {
  if (!s.startsWith('<<', i) || s.charAt(i + 2) === '<') return undefined
  let k = i + 2
  const strip = s.charAt(k) === '-'
  if (strip) k++
  while (s.charAt(k) === ' ' || s.charAt(k) === '\t') k++
  const m = /^(?:'([^']*)'|"([^"]*)"|\\?([^\s;&|<>()]+))/.exec(s.slice(k))
  if (!m) return undefined
  const delim = m[1] ?? m[2] ?? m[3] ?? ''
  return { delim, strip, quoted: m[1] !== undefined || m[2] !== undefined || m[0].startsWith('\\'), end: k + m[0].length }
}

/** From the newline at `nl`, skip a heredoc body through its delimiter line; returns the index after it. */
function skipBody(s: string, nl: number, hd: { delim: string; strip: boolean }): { body: string; end: number } {
  let at = nl + 1
  while (at <= s.length) {
    const eol = s.indexOf('\n', at)
    const line = s.slice(at, eol < 0 ? s.length : eol)
    if ((hd.strip ? line.replace(/^\t+/, '') : line) === hd.delim) return { body: s.slice(nl + 1, at), end: eol < 0 ? s.length : eol }
    if (eol < 0) break
    at = eol + 1
  }
  return { body: s.slice(nl + 1), end: s.length }
}

/** `$(…)`, `<(…)`, `>(…)` or `…` starting at `i`: the index just after it (quote- and heredoc-aware). */
function skipSub(s: string, i: number): number {
  if (s.charAt(i) === '`') {
    for (let j = i + 1; j < s.length; j++) {
      if (s.charAt(j) === '\\') j++
      else if (s.charAt(j) === '`') return j + 1
    }
    return s.length
  }
  let depth = 0
  let quote: '"' | "'" | null = null
  const pending: { delim: string; strip: boolean }[] = []
  for (let j = i + 1; j < s.length; j++) {
    const c = s.charAt(j)
    if (quote === "'") {
      if (c === "'") quote = null
    } else if (c === '\\') j++
    else if (quote === '"') {
      if (c === '"') quote = null
      else if (c === '$' && s.charAt(j + 1) === '(') j = skipSub(s, j) - 1
    } else if (c === '"' || c === "'") quote = c
    else if (c === '`' || (c === '$' && s.charAt(j + 1) === '(' && j > i + 1)) j = skipSub(s, j) - 1
    else if (c === '<' && heredoc(s, j)) {
      const hd = heredoc(s, j)
      if (hd) (pending.push(hd), (j = hd.end - 1))
    } else if (c === '\n' && pending.length > 0) {
      for (const hd of pending.splice(0)) j = skipBody(s, j, hd).end
      j-- // land on the delimiter line's newline next
    } else if (c === '(') depth++
    else if (c === ')' && --depth === 0) return j + 1
  }
  return s.length
}

const opensSub = (s: string, i: number, quoted: boolean) =>
  s.charAt(i) === '`' || (s.charAt(i + 1) === '(' && (s.charAt(i) === '$' || (!quoted && (s.charAt(i) === '<' || s.charAt(i) === '>'))))

/** Shell-ish word split: quotes and backslash escapes, no expansion; a substitution stays one word. */
export function words(segment: string): string[] {
  const out: string[] = []
  let cur = ''
  let has = false
  let quote: '"' | "'" | null = null
  for (let i = 0; i < segment.length; i++) {
    const c = segment.charAt(i)
    if (quote !== "'" && opensSub(segment, i, quote === '"')) {
      const end = skipSub(segment, i)
      cur += segment.slice(i, end)
      has = true
      i = end - 1
    } else if (quote) {
      if (c === quote) quote = null
      else if (c === '\\' && quote === '"' && i + 1 < segment.length) cur += segment.charAt(++i)
      else cur += c
    } else if (c === '"' || c === "'") {
      quote = c
      has = true
    } else if (c === '\\' && i + 1 < segment.length) {
      cur += segment.charAt(++i)
      has = true
    } else if (/\s/.test(c)) {
      if (has) out.push(cur)
      cur = ''
      has = false
    } else {
      cur += c
      has = true
    }
  }
  if (has) out.push(cur)
  return out
}

/**
 * A simple command's text and the substitutions inside it; a subshell's `(` / `)`; or a heredoc
 * body with the texts of the commands on its line (any of them may read it: `cat <<EOF | sh`).
 */
type Seg =
  | { kind: 'cmd'; text: string; subs: string[] }
  | { kind: 'open' }
  | { kind: 'close' }
  | { kind: 'heredoc'; body: string; quoted: boolean; line: string[] }

/** Split on newline ; & | ( ) outside quotes and substitutions; skip comments; heredoc bodies apart. */
export function lex(command: string): Seg[] {
  const s = command
  const out: Seg[] = []
  let cur = ''
  let subs: string[] = []
  let quote: '"' | "'" | null = null
  const pending: { delim: string; strip: boolean; quoted: boolean }[] = []
  let lineStart = 0
  const flush = () => {
    if (cur.trim() !== '' || subs.length > 0) out.push({ kind: 'cmd', text: cur, subs })
    cur = ''
    subs = []
  }
  for (let i = 0; i < s.length; i++) {
    const c = s.charAt(i)
    if (quote === "'") {
      cur += c
      if (c === "'") quote = null
    } else if (c === '\\' && s.charAt(i + 1) === '\n') {
      cur += ' '
      i++
    } else if (c === '\\') {
      cur += s.slice(i, i + 2)
      i++
    } else if (opensSub(s, i, quote === '"')) {
      const end = skipSub(s, i)
      const open = c === '`' ? 1 : 2
      const closed = end - 1 >= i + open && s.charAt(end - 1) === (c === '`' ? '`' : ')')
      subs.push(s.slice(i + open, closed ? end - 1 : end))
      cur += s.slice(i, end)
      i = end - 1
    } else if (quote === '"') {
      cur += c
      if (c === '"') quote = null
    } else if (c === '"' || c === "'") {
      cur += c
      quote = c
    } else if (c === '#' && (cur === '' || /\s$/.test(cur))) {
      const eol = s.indexOf('\n', i)
      i = (eol < 0 ? s.length : eol) - 1
    } else if (c === '<' && heredoc(s, i)) {
      const hd = heredoc(s, i)
      if (hd) (pending.push(hd), (cur += s.slice(i, hd.end)), (i = hd.end - 1))
    } else if (c === '&' && (/[<>]$/.test(cur) || s.charAt(i + 1) === '>')) {
      cur += c // >&2, 2>&1, &> are redirections, not separators
    } else if (c === '\n' || c === ';' || c === '&' || c === '|') {
      flush()
      if (c === '\n') {
        const line = out.slice(lineStart).flatMap(seg => (seg.kind === 'cmd' ? [seg.text] : []))
        for (const hd of pending.splice(0)) {
          const { body, end } = skipBody(s, i, hd)
          out.push({ kind: 'heredoc', body, quoted: hd.quoted, line })
          i = end - 1
        }
        lineStart = out.length
      }
    } else if (c === '(' || c === ')') {
      flush()
      out.push({ kind: c === '(' ? 'open' : 'close' })
    } else cur += c
  }
  flush()
  return out
}

/** Drop redirections (`> f`, `2>/dev/null`, `2>&1`, `<<EOF`): they aren't operands. */
function dropRedirects(argv: readonly string[]): string[] {
  const out: string[] = []
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i] ?? ''
    if (/^(\d*|&)(>>?|<<?<?)(&\d*-?)?$/.test(a) && !/&\d/.test(a)) i++ // bare operator: its target is the next word
    else if (!/^(\d*|&)(>>?|<<?<?)/.test(a)) out.push(a)
  }
  return out
}

const KEYWORDS = new Set(['if', 'then', 'do', 'else', 'elif', 'while', 'until', '!', '{', 'time', 'command', 'builtin', 'exec', 'nohup'])

/** Strip what runs the real command: keywords, VAR=x, env / sudo / nice / timeout and their options. */
function unwrap(argv: readonly string[]): string[] {
  let a = [...argv]
  for (;;) {
    const w = a[0]
    if (w === undefined) return a
    if (KEYWORDS.has(w) || /^[A-Za-z_]\w*=/.test(w)) a = a.slice(1)
    else if (w === 'env') {
      a = a.slice(1)
      while (a[0]?.startsWith('-')) {
        const f = a.shift()
        if (f === '-u' || f === '-C' || f === '-P') a.shift()
        else if (f === '-S') a = [...words(a.shift() ?? ''), ...a]
      }
    } else if (w === 'sudo') {
      a = a.slice(1)
      while (a[0]?.startsWith('-')) if (/^-[ugpChrtTDU]$/.test(a.shift() ?? '')) a.shift()
    } else if (w === 'nice') {
      a = a.slice(1)
      while (a[0]?.startsWith('-')) if (a.shift() === '-n') a.shift()
    } else if (w === 'timeout') {
      a = a.slice(1)
      while (a[0]?.startsWith('-')) if (/^-[sk]$/.test(a.shift() ?? '')) a.shift()
      a = a.slice(1) // the duration
    } else return a
  }
}

/** `git [-C dir] [-c k=v] [--flag] <sub> …`: the subcommand and its index. */
function gitSub(argv: readonly string[]): { sub: string | undefined; at: number } {
  let i = 1
  while (i < argv.length && (argv[i] ?? '').startsWith('-')) i += argv[i] === '-C' || argv[i] === '-c' ? 2 : 1
  return { sub: argv[i], at: i }
}

const redactUrl = (s: string) => s.replace(/\/\/[^/@\s]+@/g, '//***@')

/** `git [-C dir] [-c k=v] push …` → remote, refspecs, flags; undefined if not a push. */
export function gitPush(argv: readonly string[]): { remote: string; refs: string[]; flags: string[] } | undefined {
  if (argv[0] !== 'git') return undefined
  const { sub, at } = gitSub(argv)
  if (sub !== 'push') return undefined
  const rest = argv.slice(at + 1)
  const flags = rest.filter(a => a.startsWith('-'))
  const pos = rest.filter(a => !a.startsWith('-')).map(redactUrl)
  return { remote: pos[0] ?? '(default remote)', refs: pos.length > 1 ? pos.slice(1) : ['(current branch)'], flags }
}

// Subcommands that never push: a `push` word under them (`git stash push`) is understood.
const GIT_NO_PUSH = new Set(
  'stash log commit show diff status add fetch pull remote branch checkout switch grep tag reflog help rev-parse notes config blame restore reset merge rebase cherry-pick ls-files describe shortlog mv rm init clone apply am format-patch bisect clean gc fsck show-ref for-each-ref rev-list cat-file ls-remote range-diff'.split(' '),
)
// Commands that only print or match their arguments: `echo "git push"` runs nothing.
const NON_EXEC = new Set('echo printf grep egrep fgrep rg head tail wc cat less man which type true false : test [ [[ export local declare readonly unset read'.split(' '))
const SHELLS = /^(ba|z|da|k)?sh$/
const DELETERS = /^(rm|trash)$/
const MENTIONS_PUSH = /\bgit\b[\s\S]*\bpush\b/

export function normalize(path: string): string {
  const parts: string[] = []
  for (const part of path.split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') parts.pop()
    else parts.push(part)
  }
  return `/${parts.join('/')}`
}

/** Absolute path of a target, or null when it can't be placed: a `$`, a backtick, `~user`, or an unknown cwd. */
export function resolveTarget(arg: string, cwd: string | null, home: string): string | null {
  const expanded = arg.replace(/^(~|\$HOME|\$\{HOME\})(?=\/|$)/, home)
  if (/[$`]/.test(expanded) || expanded.startsWith('~')) return null
  if (expanded.startsWith('/')) return normalize(expanded)
  return cwd === null ? null : normalize(`${cwd}/${expanded}`)
}

export function insideVault(path: string, vaultRoot: string | null): boolean {
  if (vaultRoot === null) return false
  const root = normalize(vaultRoot)
  return path === root || path.startsWith(`${root}/`)
}

/** Strictly under one of the roots (the root itself never counts). */
function underAny(path: string, roots: readonly string[]): boolean {
  return roots.some(r => {
    const root = normalize(r)
    return root !== '/' && path.startsWith(`${root}/`)
  })
}

/** One thing the dialog asks about: its title piece, dialog lines, and log summary piece. */
type Ask = { action: string; lines: string[]; part: string }
type Acc = { asks: Ask[]; exempt: string[]; createdHits: string[] }

function operands(argv: readonly string[]): string[] {
  const dashes = argv.indexOf('--')
  return argv.slice(1).filter((a, i) => (dashes >= 0 && i + 1 > dashes) || !a.startsWith('-'))
}

/** rm / trash targets: vault skipped, temp and session files exempt, everything else asked. */
function deletes(verb: string, targets: readonly string[], cwd: string | null, ctx: PathContext, acc: Acc): void {
  const asked: string[] = []
  for (const raw of targets) {
    const p = resolveTarget(raw, cwd, ctx.home)
    if (p === null) asked.push(`${raw} (unresolved)`)
    else if (insideVault(p, ctx.vaultRoot)) continue
    else if (underAny(p, ctx.tmpRoots)) acc.exempt.push(`${verb} ${p} (tmp)`)
    else if (ctx.created.includes(p)) (acc.exempt.push(`${verb} ${p} (session file)`), acc.createdHits.push(p))
    else asked.push(p)
  }
  if (asked.length === 0) return
  const lines = asked.slice(0, 8).map(p => `${verb}: ${p}`)
  if (asked.length > 8) lines.push(`${verb}: … ${asked.length - 8} more`)
  acc.asks.push({
    action: `${verb} ${asked.length === 1 ? 'a file' : `${asked.length} files`} outside the vault`,
    lines,
    part: `${verb} ${asked.slice(0, 3).join(' ')}${asked.length > 3 ? ` (+${asked.length - 3})` : ''}`,
  })
}

/** `find <roots> … -exec rm` / `-delete`: gated when a root is outside the vault or can't be placed. */
function findDelete(argv: readonly string[], cwd: string | null, ctx: PathContext, acc: Acc): void {
  const exec = argv.findIndex((a, i) => /^-(exec|execdir|ok|okdir)$/.test(a) && DELETERS.test((argv[i + 1] ?? '').split('/').pop() ?? ''))
  if (exec < 0 && !argv.includes('-delete')) return
  const verb = exec >= 0 ? `find -exec ${(argv[exec + 1] ?? '').split('/').pop()}` : 'find -delete'
  let i = 1
  while (/^-[HLPEX]$/.test(argv[i] ?? '')) i++
  const roots: string[] = []
  while (i < argv.length && !/^[-(!]/.test(argv[i] ?? '')) roots.push(argv[i++] ?? '')
  const asked: string[] = []
  for (const raw of roots.length ? roots : ['.']) {
    const p = resolveTarget(raw, cwd, ctx.home)
    if (p === null) asked.push(`${raw} (unresolved)`)
    else if (insideVault(p, ctx.vaultRoot)) continue
    else if (underAny(p, ctx.tmpRoots)) acc.exempt.push(`${verb} under ${p} (tmp)`)
    else asked.push(p)
  }
  if (asked.length === 0) return
  acc.asks.push({ action: `${verb} under ${asked.length === 1 ? 'a folder' : `${asked.length} folders`} outside the vault`, lines: asked.map(p => `${verb} under: ${p}`), part: `${verb} under ${asked.join(' ')}` })
}

function unparsedPush(argv: readonly string[], acc: Acc): void {
  const text = redactUrl(clip(argv.join(' '), 120))
  acc.asks.push({ action: 'run a command that may git push', lines: [`command: ${text}`], part: `unparsed git push: ${text}` })
}

/** Walk one command string; returns the cwd it leaves behind (for `eval`). */
function walk(command: string, start: string | null, ctx: PathContext, acc: Acc, depth: number): string | null {
  if (depth > 8) {
    if (MENTIONS_PUSH.test(command)) unparsedPush([command], acc)
    return null
  }
  let cwd = start
  const stack: (string | null)[] = []
  for (const seg of lex(command)) {
    if (seg.kind === 'open') stack.push(cwd)
    else if (seg.kind === 'close') cwd = stack.length ? (stack.pop() ?? null) : cwd
    else if (seg.kind === 'heredoc') heredocBody(seg, cwd, ctx, acc, depth)
    else {
      for (const sub of seg.subs) walk(sub, cwd, ctx, acc, depth + 1)
      cwd = step(unwrap(dropRedirects(words(seg.text))), cwd, ctx, acc, depth)
    }
  }
  return cwd
}

/**
 * A heredoc body is data to `cat`/`echo`/`git commit`, a script to a shell, and unknown to
 * anything else (python, ssh…): gated there when it mentions git and push.
 */
function heredocBody(seg: { body: string; quoted: boolean; line: string[] }, cwd: string | null, ctx: PathContext, acc: Acc, depth: number): void {
  // An unquoted delimiter still expands $(…) and `…` in the body.
  if (!seg.quoted) for (const s of lex(seg.body)) if (s.kind === 'cmd') for (const sub of s.subs) walk(sub, cwd, ctx, acc, depth + 1)
  const readers = seg.line.map(t => unwrap(dropRedirects(words(t)))).filter(a => a.length > 0)
  const base = (a: readonly string[]) => (a[0] ?? '').split('/').pop() ?? ''
  if (readers.some(a => SHELLS.test(base(a)) && !a.slice(1).some(f => /^-[a-zA-Z]*c[a-zA-Z]*$/.test(f)))) {
    walk(seg.body, cwd, ctx, acc, depth + 1)
    return
  }
  const dataOnly = readers.every(a => NON_EXEC.has(base(a)) || (base(a) === 'git' && GIT_NO_PUSH.has(gitSub(a).sub ?? '')))
  if (!dataOnly && MENTIONS_PUSH.test(seg.body)) unparsedPush([...(readers[0] ?? []), '<<heredoc'], acc)
}

/** Classify one simple command; returns the cwd after it. */
function step(argv: string[], cwd: string | null, ctx: PathContext, acc: Acc, depth: number): string | null {
  const cmd = argv[0]
  if (cmd === undefined) return cwd
  const base = cmd.split('/').pop() ?? cmd
  if (base === 'cd' || base === 'pushd') {
    const to = argv[1]
    return to === undefined ? ctx.home : to === '-' ? null : resolveTarget(to, cwd, ctx.home)
  }
  if (base === 'popd') return null
  if (base === 'eval') return walk(argv.slice(1).join(' '), cwd, ctx, acc, depth + 1)
  if (SHELLS.test(base)) {
    const flag = argv.findIndex((a, i) => i > 0 && /^-[a-zA-Z]*c[a-zA-Z]*$/.test(a))
    const script = flag > 0 ? argv[flag + 1] : undefined
    if (script !== undefined) walk(script, cwd, ctx, acc, depth + 1)
    else if (MENTIONS_PUSH.test(argv.join(' '))) unparsedPush(argv, acc)
    return cwd
  }
  if (base === 'git') {
    argv = ['git', ...argv.slice(1)]
    const push = gitPush(argv)
    if (push) {
      const lines = [`remote: ${push.remote}`, `refs: ${push.refs.join(', ')}`]
      if (push.flags.length) lines.push(`flags: ${push.flags.join(' ')}`)
      acc.asks.push({ action: 'git push', lines, part: `git push ${push.remote} ${push.refs.join(' ')}${push.flags.length ? ` ${push.flags.join(' ')}` : ''}` })
    } else {
      // A subcommand held in a variable (`git $x`) can't be told apart from push.
      const sub = gitSub(argv).sub ?? ''
      if (/[$`]/.test(sub) || (!GIT_NO_PUSH.has(sub) && argv.slice(1).some(a => /\bpush\b/.test(a)))) unparsedPush(argv, acc)
    }
    return cwd
  }
  // A command word held in a variable (`$G push`): unknown command, so a push word gates it.
  if (/[$`]/.test(cmd) && argv.some(a => /\bpush\b/.test(a))) {
    unparsedPush(argv, acc)
    return cwd
  }
  if (DELETERS.test(base)) {
    deletes(base, operands(argv), cwd, ctx, acc)
    return cwd
  }
  if (base === 'mv') {
    const ops = operands(argv)
    const dest = ops.length >= 2 ? resolveTarget(ops[ops.length - 1] ?? '', cwd, ctx.home) : null
    const trash = normalize(`${ctx.home}/.Trash`)
    if (dest !== null && (dest === trash || dest.startsWith(`${trash}/`))) deletes('trash', ops.slice(0, -1), cwd, ctx, acc)
    return cwd
  }
  if (base === 'xargs' && argv.slice(1).some(a => /(^|[\s/])(rm|trash)(\s|$)/.test(a))) {
    acc.asks.push({ action: 'xargs rm (targets unknown)', lines: ['xargs rm: targets come from input (unknown)'], part: 'xargs rm (targets unknown)' })
    return cwd
  }
  if (base === 'find') findDelete(argv, cwd, ctx, acc)
  if (!NON_EXEC.has(base) && MENTIONS_PUSH.test(argv.join(' '))) unparsedPush(argv, acc)
  return cwd
}

/** What a Bash command needs: a dialog (`gated`), and what passed as exempt (logged either way). */
export type BashGate = { gated: Gated | undefined; exempt: string[]; createdHits: string[] }

export function classifyBash(command: string, ctx: PathContext): BashGate {
  const acc: Acc = { asks: [], exempt: [], createdHits: [] }
  walk(command, ctx.cwd, ctx, acc, 0)
  if (acc.asks.length === 0) return { gated: undefined, exempt: acc.exempt, createdHits: acc.createdHits }
  const tail = acc.exempt.length ? ` · exempt: ${acc.exempt.join('; ')}` : ''
  const gated = { title: acc.asks.map(a => a.action).join(' and '), lines: acc.asks.flatMap(a => a.lines), summary: `${acc.asks.map(a => a.part).join('; ')}${tail}` }
  return { gated, exempt: acc.exempt, createdHits: acc.createdHits }
}

/** Gate a Bash command: any non-force `git push` (however wrapped), or a delete outside the vault. */
export function gatedBash(command: string, ctx: PathContext): Gated | undefined {
  return classifyBash(command, ctx).gated
}

// ---- off switch, status, log -----------------------------------------------

export function parseMode(value: unknown): Mode | undefined {
  return value === 'auto' || value === 'on' || value === 'off' ? value : undefined
}

/** "8h" / "30m" / "2d" / "45" (minutes) → ms; undefined when unreadable. */
export function parseDuration(text: string): number | undefined {
  const m = /^(\d+(?:\.\d+)?)\s*([mhd]?)$/i.exec(text.trim())
  if (!m) return undefined
  const n = Number(m[1])
  const unit = (m[2] ?? '').toLowerCase()
  const ms = n * (unit === 'h' ? 3_600_000 : unit === 'd' ? 86_400_000 : 60_000)
  return ms > 0 ? ms : undefined
}

export function formatLeft(ms: number): string {
  const min = Math.max(1, Math.ceil(ms / 60_000))
  if (min < 60) return `${min}m`
  const h = Math.floor(min / 60)
  return min % 60 ? `${h}h${min % 60}m` : `${h}h`
}

export function clip(text: string, max: number): string {
  const one = text.replace(/\s+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, max - 1)}…` : one
}

/** Local time as 2026-10-02T23:14:05+02:00. */
export function localStamp(ms: number): string {
  const d = new Date(ms)
  const off = -d.getTimezoneOffset()
  const pad = (n: number) => String(Math.floor(Math.abs(n))).padStart(2, '0')
  const local = new Date(ms + off * 60_000).toISOString().slice(0, 19)
  return `${local}${off >= 0 ? '+' : '-'}${pad(off / 60)}:${pad(off % 60)}`
}

export function logLine(f: { at: number; session: string; mode: Mode; tool: string; summary: string; decision: Decision }): string {
  return [localStamp(f.at), `session=${f.session}`, `mode=${f.mode}`, `tool=${f.tool}`, `decision=${f.decision}`, `payload=${clip(f.summary, 200)}`].join('\t')
}

export function denyReason(title: string, verdict: 'denied' | 'timed-out' | 'headless-strict', timeoutMin: number): string {
  const why =
    verdict === 'timed-out'
      ? `unattended — not approved (no answer within ${timeoutMin} min)`
      : verdict === 'headless-strict'
        ? 'gate mode is "on" and this session is headless, so nobody can approve it'
        : 'the user denied it in the confirm dialog'
  return `outward-gate: ${title} was blocked — ${why}. Do not retry it or route around it (no other tool to the same end). Continue with your other work and list this blocked action in your closeout.`
}

