/** How a confirm dialog ended. */
export type GateVerdict = 'approved' | 'denied' | 'timed-out'

/** A session-scoped `/gate off`: `until` epoch ms, or null for "until /gate on". */
export type GateOff = { until: number | null }

/**
 * The `$.gate` noun. Its only job is the wait: a `$` call's time never counts
 * against a hook's 10 s budget, while awaiting a plain promise does (and a hook
 * that overruns is skipped, i.e. the tool would run: fail-open). The engine also
 * bounds each noun call to 10 s, so a wait answers 'pending' every few seconds
 * and the caller asks again.
 */
export type Gate = {
  /** The dialog's verdict once there is one, else 'pending' at the next pulse. */
  wait: (args: { id: string }) => Promise<GateVerdict | 'pending'>
}

declare module 'claude-code' {
  interface EngineInterface {
    gate: Gate
  }
  interface PluginState {
    'outward-gate': {
      /** Session off switch; null while the gate is on. */
      off: GateOff | null
      /**
       * Absolute paths a Write created this session (not ones it overwrote), plus where they
       * resolve; an rm whose targets all match exactly passes with no dialog. Capped at 500.
       */
      created: string[]
    }
  }
}
